from pathlib import Path
import hashlib,json,math,statistics
r=Path(__file__).resolve().parent
def read(name):
 p=next((r/name).glob('*/metrics.json'));x=json.loads(p.read_text());assert x['completed'];return x,{'path':str(p.relative_to(r)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def q(v,p):
 v=sorted(v);i=(len(v)-1)*p;return v[int(i)]+(v[min(int(i)+1,len(v)-1)]-v[int(i)])*(i%1)
c1,s1=read('prefix-count-c1-v1');c4,s4=read('prefix-count-c4-v1');quality,sq=read('prefix-count-quality-v1');cached,sk=read('prefix-count-cached-v1');cancel,sc=read('prefix-count-cancel-v1')
formal=[z for z in c4['rows'] if z['phase']=='formal'];assert len(formal)==384 and len(c4['blocks'])==12 and all(z['numeric_pass'] and z['functional_pass'] for z in formal)
assert len([z for z in c1['rows'] if z['phase']=='formal'])==24
cycles=[]
for i in range(3):
 blocks=c4['blocks'][i*4:(i+1)*4];rates={m:sum(z['output_tokens'] for z in blocks if z['mode']==m)/sum(z['seconds'] for z in blocks if z['mode']==m) for m in ['native','adaptive']};cycles.append({'index':i,'rates':rates,'candidate_over_native':rates['adaptive']/rates['native']})
pooled={m:{k:{'median':statistics.median(z[k] for z in formal if z['mode']==m),'p95_linear':q([z[k] for z in formal if z['mode']==m],.95)} for k in ['TTFT_ms','last_token_ms','mean_TPOT_ms']} for m in ['native','adaptive']}
case_ratios={case:{k:c1['summary']['adaptive']['cases'][case][k]/c1['summary']['native']['cases'][case][k] for k in ['TTFT_ms','last_token_ms','mean_TPOT_ms']} for case in c1['summary']['native']['cases']};equal={k:math.exp(statistics.mean(math.log(z[k]) for z in case_ratios.values())) for k in ['TTFT_ms','last_token_ms','mean_TPOT_ms']}
counters={}
for mode in ['native','adaptive']:
 blocks=[z for z in c4['blocks'] if z['mode']==mode];values={k:sum(z['native_counter_boundary']['delta']['33'][k] for z in blocks) for k in blocks[0]['native_counter_boundary']['delta']['33']};seconds=sum(z['seconds'] for z in blocks);generated=values['vllm:generation_tokens_total'];drafts=values['vllm:spec_decode_num_drafts_total'];assert generated==18432
 counters[mode]={'totals':values,'timed_block_seconds':seconds,'generated_per_draft':generated/drafts,'accepted_per_draft':values['vllm:spec_decode_num_accepted_tokens_total']/drafts,'drafts_per_second':drafts/seconds,'generated_per_second':generated/seconds,'scope':'Exact mode-owned completed blocks, native counters settled to output budget and two stable snapshots outside timers. Draft count is native per-request proposal accounting, not device batch invocation count.'}
eff=counters['adaptive']['generated_per_draft']/counters['native']['generated_per_draft'];work=counters['adaptive']['drafts_per_second']/counters['native']['drafts_per_second'];ratio=c4['summary']['adaptive']['output_tokens_per_s']/c4['summary']['native']['output_tokens_per_s'];assert abs(eff*work-ratio)<1e-8
result={'decision':'PENDING_REVIEW','sources':[s1,s4,sq,sk,sc],'C1':c1['summary'],'C1_case_ratios':case_ratios,'C1_equal_case_ratios':equal,'C1_sequence_comparisons':c1['sequence_comparisons'],'C1_request_counter_boundaries':[{'case':z['case_id'],'mode':z['mode'],'phase':z['phase'],'counts':z['native_counter_boundary']} for z in c1['rows']],'C4':c4['summary'],'C4_candidate_over_native':ratio,'C4_cycles':cycles,'C4_pooled':pooled,'C4_blocks':c4['blocks'],'C4_mode_owned_counters':counters,'C4_accounting_identity':{'generated_per_draft_ratio':eff,'drafts_per_second_ratio':work,'product':eff*work,'scope':'Accounting identity, not a causal separation of acceptance, GPU service and host waiting.'},'C4_sequence_comparisons':c4['sequence_comparisons'],'quality':{'summary':quality['summary'],'sequence_comparisons':quality['sequence_comparisons'],'full64_equal_cases':sum(z['all_same'] for z in quality['sequence_comparisons'].values())},'cached':cached['summary'],'cancel':{k:cancel.get(k) for k in ['completed','client_close_requests','full_reuse_and_peer_responses','backend_abort_log_request_count','abort_counter_deltas']},'representation':'Original AllGather routing directly returns int64 prefix0 for original fusedGMM1. Original pinned cumsum_group_list(0,1) diff/cat at GMM2 recovers int64 count and original type1; actual75 prefix/fused/restore startup calls required per selected graph. Same-instance native/prefix target graph families captured before real requests through independent native warmup/capture contexts and separate comparison pools, native sync/replay retained; MTP remains original count histogram in BOTH arms. Target-only selector fixed in both arms. RoPE contiguous source enabled in BOTH modes. Three graph families (native/replica/prefix) are a research comparison cost, not a production capacity claim.','scope':'Finite true PD stock-proxy ordinary64/128, same pinned P/D, observer/profile/export/related transfers off, C1 ABBAx3 and balanced rotated C4 four slots x8/block ABBAx3. No general-quality, SLO maximum capacity or global optimum claim.'}
(r/'prefix-count-formal-verdict-v1.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'C1_equal_case_ratios':equal,'C4_candidate_over_native':ratio,'C4_cycles':cycles,'C4_mode_owned_counters':counters,'quality_full64_equal_cases':result['quality']['full64_equal_cases'],'cancel':result['cancel']}))
